  // 记录操作日志辅助函数
  function logOp(text) {
    var d = new Date();
    var pad = function(n){ return n<10?'0'+n:n; };
    var t = d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+' '+pad(d.getHours())+':'+pad(d.getMinutes());
    MEMBER_CONFIG.opLogs.unshift({ time: t, user: '唐美芳', text: text });
    if (MEMBER_CONFIG.opLogs.length > 8) MEMBER_CONFIG.opLogs.pop();
  }

