  var BENEFIT_ALIAS = { '免费升舱':'免费升舱','酒店延迟退房':'酒店延迟退房','景点折扣':'景点折扣','定制抵扣券':'定制抵扣券','生日礼包':'生日礼包','积分加速':'积分加速' };
  function iconFor(name) {
    return BENEFIT_ICONS[name] || BENEFIT_ICONS[BENEFIT_ALIAS[name]] || BENEFIT_ICONS['升级礼包'];
  }

