  // ====== C端 小程序导航栏 ======
  var cPageSource = {}; // 记录每个子页面的来源页 { member: 'home', ucoin: 'member', ai: 'member' }
  function getCNavBar(title, showBack) {
    var sigIcon = '<svg width="14" height="10" viewBox="0 0 18 12" fill="currentColor"><rect x="0" y="8" width="3" height="4" rx="0.5"/><rect x="5" y="5" width="3" height="7" rx="0.5"/><rect x="10" y="2" width="3" height="10" rx="0.5"/><rect x="15" y="0" width="3" height="12" rx="0.5"/></svg>';
    var batteryIcon = '<svg width="18" height="10" viewBox="0 0 24 12" fill="none" stroke="currentColor" stroke-width="1"><rect x="1" y="1" width="20" height="10" rx="2"/><rect x="22" y="4" width="1.5" height="4" rx="0.5" fill="currentColor"/><rect x="2.5" y="2.5" width="13" height="7" rx="1" fill="currentColor"/></svg>';
    var statusBar = '<div class="c-nav-status">' +
      '<span class="c-nav-time">9:41</span>' +
      '<span class="c-nav-sig">5G ' + sigIcon + ' ' + batteryIcon + '</span>' +
      '</div>';
    var navBar = '<div class="c-nav-bar">' +
      (showBack
        ? '<div class="c-nav-back" data-action="back"><svg width="12" height="20" viewBox="0 0 12 20" fill="currentColor"><path d="M10 2L2 10L10 18" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg></div>'
        : '<div class="c-nav-placeholder"></div>') +
      '<div class="c-nav-title">' + title + '</div>' +
      '<div class="c-nav-placeholder"></div>' +
      '</div>';
    return '<div class="c-nav-wrap">' + statusBar + navBar + '</div>';
  }

  // ====== C端 统一底部Tab栏 ======
  function getCTabBarHTML(active) {
    var tabs = [
      { label: '首页', page: 'home', icon: 'M10 20v-6h4v6h5v-8h3L12 3 2 12h3v8z' },
      { label: '客服', page: 'service', icon: 'M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z' },
      { label: '订单', page: 'orders', icon: 'M19 3h-4.18C14.4 1.84 13.3 1 12 1c-1.3 0-2.4.84-2.82 2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-7 0c.55 0 1 .45 1 1s-.45 1-1 1-1-.45-1-1 .45-1 1-1zm2 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z' },
      { label: '我的', page: 'profile', icon: 'M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z' }
    ];
    return '<div class="c-tab-bar-v2">' + tabs.map(function(t) {
      return '<div class="tab-bar-item-v2 c' + (t.page === active ? ' active' : '') + '" data-page="' + t.page + '"><svg width="22" height="22" viewBox="0 0 24 24" fill="currentColor"><path d="' + t.icon + '"/></svg><span>' + t.label + '</span></div>';
    }).join('') + '</div>';
  }

  // ====== DOM 引用 ======
  var $platformBtns = document.querySelectorAll('.platform-btn');
  var $platformContent = document.getElementById('platform-content');
  var $platformHeader = document.getElementById('platform-header');
  var $platformTitle = document.getElementById('platform-title');
  var $platformDot = document.getElementById('platform-dot');
  var $pageNav = document.getElementById('page-nav');

  // ====== 初始化 ======
  function init() {
    // 平台切换按钮
    $platformBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        switchPlatform(this.dataset.platform);
      });
    });
    
    // 使用事件委托处理侧边栏点击（全局监听，无需重复绑定）
    document.addEventListener('click', function(e) {
      var item = e.target.closest('.pc-sidebar-item');
      if (item && !item.hasAttribute('data-has-flyout')) {
        var page = item.dataset.page;
        if (page) {
          var cfg = PLATFORMS[currentPlatform];
          if (cfg && cfg.pages.indexOf(page) !== -1) {
            // 更新active状态
            var sidebar = item.closest('.pc-sidebar-menu');
            if (sidebar) {
              sidebar.querySelectorAll('.pc-sidebar-item').forEach(function(i) {
                i.classList.remove('active');
              });
              item.classList.add('active');
            }
            switchPage(currentPlatform, page);
          }
        } else {
          var label = item.querySelector('span');
          if (label) {
            showToast(label.textContent.trim() + ' - 功能开发中');
          }
        }
      }
    });
    
    // ====== UBK 系统交互事件委托 ======
    document.addEventListener('click', function(e) {
      // 表格操作按钮（vproducts页面有专用处理器，此处跳过）
      var actionEl = e.target.closest('[class*="ubk-action-"]');
      if (actionEl) {
        var ubkPageCheck = actionEl.closest('[id^="page-ubk-"]');
        if (ubkPageCheck && ubkPageCheck.id === 'page-ubk-vproducts') {
          // vproducts 页面由专用事件委托处理（编辑/套餐/上架/下架）
        } else {
          var text = actionEl.textContent.trim();
          var row = actionEl.closest('tr');
          var productName = row ? (row.querySelector('.ubk-prod-name, .ubk-order-no, .ubk-bill-no') || {}).textContent : '';
          if (actionEl.classList.contains('ubk-action-detail')) {
            showToast('查看' + (productName ? '：' + productName : '详情'));
          } else if (actionEl.classList.contains('ubk-action-plan')) {
            showToast('套餐管理：' + (productName || ''));
          } else if (actionEl.classList.contains('ubk-action-toggle')) {
            showToast(text + '操作成功');
          } else if (actionEl.classList.contains('ubk-action-progress')) {
            showToast('查看订单进度：' + (productName || ''));
          } else if (actionEl.classList.contains('ubk-action-return')) {
            showToast('资料回传：' + (productName || ''));
          } else if (actionEl.classList.contains('ubk-action-pay')) {
            showToast('发起付款：' + (productName || ''));
          } else if (actionEl.classList.contains('ubk-action-bill')) {
            showToast('查看账单明细：' + (productName || ''));
          }
          return;
        }
      }
      
      // 工具栏按钮（vproducts页面有专用处理器，此处跳过）
      var toolbarBtn = e.target.closest('.ubk-btn-primary, .ubk-btn-query, .ubk-btn-export');
      if (toolbarBtn) {
        var tbPageCheck = toolbarBtn.closest('[id^="page-ubk-"]');
        if (tbPageCheck && tbPageCheck.id === 'page-ubk-vproducts') {
          // vproducts 页面由专用事件委托处理
        } else {
          var btnText = toolbarBtn.textContent.trim();
          if (toolbarBtn.classList.contains('ubk-btn-primary')) {
            showToast(btnText + ' · 打开产品录入表单');
          } else if (toolbarBtn.classList.contains('ubk-btn-query')) {
            showToast('正在查询...');
          } else if (toolbarBtn.classList.contains('ubk-btn-export')) {
            showToast('导出成功，请到下载中心查看');
          }
          return;
        }
      }
      
      // 分页按钮
      var pageBtn = e.target.closest('.ubk-page-btn');
      if (pageBtn && !pageBtn.classList.contains('ubk-page-dots')) {
        var pageText = pageBtn.textContent.trim();
        if (pageText === '上一页' || pageText === '下一页') {
          showToast(pageText);
        } else {
          // 更新分页active状态
          var pageBtns = pageBtn.parentElement.querySelectorAll('.ubk-page-btn');
          pageBtns.forEach(function(b) { b.classList.remove('active'); });
          pageBtn.classList.add('active');
          showToast('第 ' + pageText + ' 页');
        }
        return;
      }
      
      // 时间筛选按钮
      var timeBtn = e.target.closest('.ubk-time-btn');
      if (timeBtn) {
        timeBtn.parentElement.querySelectorAll('.ubk-time-btn').forEach(function(b) { b.classList.remove('active'); });
        timeBtn.classList.add('active');
        return;
      }
      
      // 快捷入口
      var quickItem = e.target.closest('.ubk-quick-item');
      if (quickItem) {
        var quickName = quickItem.querySelector('span');
        if (quickName) showToast(quickName.textContent.trim());
        return;
      }
      
      // 顶部栏链接
      var topLink = e.target.closest('.ubk-topbar-link');
      if (topLink) {
        var linkText = topLink.textContent.trim().replace(/\d+\+/, '').trim();
        showToast(linkText);
        return;
      }
      
      // "更多"链接
      var moreLink = e.target.closest('.ubk-more');
      if (moreLink) {
        showToast('查看更多');
        return;
      }
    });
    
    // 初始渲染
    switchPlatform('c');
  }

  // ====== 平台切换 ======
  function switchPlatform(platform) {
    currentPlatform = platform;
    if (!currentPage[platform]) {
      currentPage[platform] = PLATFORMS[platform].pages[0];
    }
    updatePlatformUI();
    renderPlatformContent();
    renderPageNav();
    switchPage(platform, currentPage[platform]);
  }

  function updatePlatformUI() {
    // 按钮状态
    $platformBtns.forEach(function(btn) {
      var isActive = btn.dataset.platform === currentPlatform;
      btn.classList.toggle('active', isActive);
      btn.classList.remove('c-active', 'b-active', 'ch-active', 'op-active', 'ubk-active');
      if (isActive) btn.classList.add(currentPlatform + '-active');
    });
    // 标题
    var cfg = PLATFORMS[currentPlatform];
    $platformTitle.textContent = cfg.name;
    $platformDot.className = 'platform-dot ' + cfg.dotClass;
    $platformHeader.style.display = 'flex';
    $platformContent.style.display = '';
  }

  // ====== 页面导航 ======
  function renderPageNav() {
    if (!$pageNav) return;
    var cfg = PLATFORMS[currentPlatform];
    var html = '';
    cfg.pages.forEach(function(p) {
      html += '<button class="page-nav-btn" data-page="' + p + '">' + cfg.pageLabels[p] + '</button>';
    });
    $pageNav.innerHTML = html;

    // 绑定事件
    $pageNav.querySelectorAll('.page-nav-btn').forEach(function(btn) {
      btn.addEventListener('click', function() {
        switchPage(currentPlatform, this.dataset.page);
      });
    });
  }

  function switchPage(platform, page) {
    currentPage[platform] = page;
    // 更新导航按钮状态
    if ($pageNav) {
      $pageNav.querySelectorAll('.page-nav-btn').forEach(function(btn) {
        btn.classList.toggle('active', btn.dataset.page === page);
      });
    }
    // 显示对应页面
    showPage(platform, page);
  }

  // ====== 页面显示 ======
  function showPage(platform, page) {
    var pageId = 'page-' + platform + '-' + page;
    var cfg = PLATFORMS[platform];
    var container = document.getElementById('platform-content');
    
    console.log('[showPage] platform:', platform, 'page:', page, 'pageId:', pageId);
    
    if (cfg.isPhone) {
      // 手机端：隐藏所有 phone-col，显示目标
      if (container) {
        container.querySelectorAll('.phone-col').forEach(function(el) {
          el.style.display = 'none';
        });
      }
      // 使用 getElementById 直接查找
      var target = document.getElementById(pageId);
      console.log('[showPage] Phone target:', target ? 'FOUND' : 'NOT FOUND');
      if (target) {
        target.style.display = 'flex';
        target.style.visibility = 'visible';
      }
    } else {
      // PC端：隐藏所有 page-section，显示目标
      if (container) {
        var sections = container.querySelectorAll('.page-section');
        console.log('[showPage] Found', sections.length, 'page-sections');
        sections.forEach(function(el) {
          el.style.display = 'none';
          el.style.visibility = 'hidden';
        });
      }
      // 使用 getElementById 直接查找
      var targetPc = document.getElementById(pageId);
      console.log('[showPage] PC target:', targetPc ? 'FOUND at #' + pageId : 'NOT FOUND');
      if (targetPc) {
        targetPc.style.display = 'block';
        targetPc.style.visibility = 'visible';
        targetPc.style.minHeight = '600px';
      } else {
        console.error('[showPage] Cannot find element:', pageId);
        // 尝试列出所有 page-section 的 ID
        if (container) {
          container.querySelectorAll('.page-section').forEach(function(el) {
            console.log('[showPage] Existing section ID:', el.id);
          });
        }
      }
    }
  }

  // ====== 渲染平台内容结构 ======
  function renderPlatformContent() {
    var cfg = PLATFORMS[currentPlatform];
    var html = '';
    if (cfg.isPhone) {
      html = '<div class="phone-row">' + getPhonePagesHTML(currentPlatform) + '</div>';
    } else {
      html = getPCPagesHTML(currentPlatform);
    }
    console.log('[renderPlatformContent] platform:', currentPlatform, 'html length:', html.length);
    console.log('[renderPlatformContent] $platformContent:', $platformContent ? 'EXISTS' : 'NULL');
    if ($platformContent) {
      $platformContent.innerHTML = html;
      console.log('[renderPlatformContent] innerHTML set, children:', $platformContent.children.length);
      // 验证第一个子元素
      var firstChild = $platformContent.firstElementChild;
      if (firstChild) {
        console.log('[renderPlatformContent] first child ID:', firstChild.id);
        console.log('[renderPlatformContent] first child display:', getComputedStyle(firstChild).display);
      }
    } else {
      console.error('[renderPlatformContent] ERROR: $platformContent is null!');
    }
    // 重新绑定页面内交互
    bindPageInteractions();
  }

  function getPhonePagesHTML(platform) {
    var cfg = PLATFORMS[platform];
    var html = '';
    cfg.pages.forEach(function(page) {
      html += '<div class="phone-col page-section" id="page-' + platform + '-' + page + '">';
      html += '<div class="phone-col-label">' + cfg.pageLabels[page] + '</div>';
      html += '<div class="phone-frame">';
      html += '<div class="phone-screen" id="phone-screen-' + platform + '-' + page + '">';
      html += getPhonePageContent(platform, page);
      html += '</div></div></div>';
    });
    return html;
  }

  function getPCPagesHTML(platform) {
    var cfg = PLATFORMS[platform];
    var html = '';
    cfg.pages.forEach(function(page, index) {
      // 第一个页面默认显示，其他隐藏
      var displayStyle = index === 0 ? 'display:block' : 'display:none';
      html += '<div class="page-section" id="page-' + platform + '-' + page + '" style="' + displayStyle + '">';
      html += getPCPageContent(platform, page);
      html += '</div>';
    });
    return html;
  }

