        var curLv = 3;
        var unlockedCount = MEMBER_CONFIG.cBenefits.filter(function(b){ return b.map[curLv]; }).length;
        var totalCount = MEMBER_CONFIG.cBenefits.length;
        // 按分类分组
        var benefitCats = {};
        MEMBER_CONFIG.cBenefits.forEach(function(b) {
          var cat = b.cat || '通用权益';
          if (!benefitCats[cat]) benefitCats[cat] = [];
          benefitCats[cat].push(b);
        });
        var catHTML =
          '<div class="lux-benefit-summary">' +
            '<div class="lux-benefit-summary-num">' + unlockedCount + '<span>/' + totalCount + '</span></div>' +
            '<div class="lux-benefit-summary-label">已解锁权益</div>' +
            '<div class="lux-benefit-summary-bar"><div style="width:' + Math.round(unlockedCount/totalCount*100) + '%"></div></div>' +
          '</div>';
        for (var cat in benefitCats) {
          if (benefitCats.hasOwnProperty(cat)) {
            var catUnlocked = benefitCats[cat].filter(function(b){ return b.map[curLv]; }).length;
            catHTML += '<div class="lux-section-label">' + cat + ' <span class="lux-section-count">' + catUnlocked + '/' + benefitCats[cat].length + '</span></div>';
            benefitCats[cat].forEach(function(b) {
              var unlocked = b.map[curLv];
              var iconPath = iconFor(b.name);
              catHTML += '<div class="lux-benefit-item' + (unlocked ? '' : ' locked') + '">' +
                '<div class="lux-benefit-icon">' +
                '<svg width="18" height="18" viewBox="0 0 24 24" fill="' + (unlocked ? '#D4AF37' : 'rgba(255,255,255,0.2)') + '"><path d="' + iconPath + '"/></svg>' +
                '</div>' +
                '<div class="lux-benefit-info">' +
                  '<div class="lux-benefit-name">' + b.name + '</div>' +
                  '<div class="lux-benefit-desc">' + (unlocked ? '已解锁 · 可使用' : '升级至更高等级解锁') + '</div>' +
                '</div>' +
                '<div class="lux-benefit-status' + (unlocked ? ' active' : '') + '">' + (unlocked ? '可用' : '锁定') + '</div>' +
                '</div>';
            });
          }
        }
        catHTML += '<div class="lux-drawer-footer">权益将随等级提升自动解锁，无需额外操作</div>';
