            var oTagText = oTag ? oTag.textContent.trim() : '';
            var oDateText = oDate ? oDate.textContent.trim() : '';
            var oPriceText = oPrice ? oPrice.textContent.trim() : '';
            var oStatusText = oStatus ? oStatus.textContent.trim() : '';
            var oImgBg = oImg ? oImg.style.background : 'linear-gradient(135deg,#FF6B6B,#FFE66D)';
            var oNoEl = card.querySelector('.co-order-no');
