  function showDetailModal(title, contentHTML, opts) {
    opts = opts || {};
    var width = opts.width || 580;
    var mask = document.createElement('div');
    mask.className = 'proto-detail-mask';
    mask.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.45);z-index:10001;display:flex;align-items:center;justify-content:center';
    var modal = document.createElement('div');
    modal.style.cssText = 'background:#fff;border-radius:14px;width:' + width + 'px;max-width:92vw;max-height:85vh;overflow:hidden;box-shadow:0 12px 48px rgba(0,0,0,0.2);display:flex;flex-direction:column;animation:protoModalIn 0.25s ease';
    modal.innerHTML =
      '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 24px;border-bottom:1px solid #F0F0F0;flex-shrink:0">' +
      '<div style="font-size:17px;font-weight:600;color:#1C1C1E">' + title + '</div>' +
      '<svg width="20" height="20" viewBox="0 0 24 24" fill="#999" style="cursor:pointer;flex-shrink:0" onclick="this.closest(\'.proto-detail-mask\').remove()"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg>' +
      '</div>' +
      '<div style="overflow-y:auto;flex:1">' + contentHTML + '</div>';
    mask.appendChild(modal);
    document.body.appendChild(mask);
    mask.addEventListener('click', function(e) { if (e.target === mask) mask.remove(); });
    return mask;
  }

  // ====== 表单弹窗（新增/编辑） ======
  function showFormModal(title, fields, onSave) {
    var mask = document.createElement('div');
    mask.className = 'proto-modal-mask';
    mask.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:10001;display:flex;align-items:center;justify-content:center';
    var modal = document.createElement('div');
    var fieldCount = fields.length;
    var modalWidth = fieldCount > 8 ? 520 : 440;
    modal.style.cssText = 'background:#fff;border-radius:14px;width:' + modalWidth + 'px;max-width:90vw;overflow:hidden;box-shadow:0 8px 32px rgba(0,0,0,0.15);animation:protoModalIn .25s cubic-bezier(0.16,1,0.3,1)';
    var fieldsHTML = fields.map(function(f) {
      var val = f.value !== undefined ? f.value : '';
      var readonlyAttr = f.readonly ? ' readonly' : '';
      var readonlyStyle = f.readonly ? 'background:#F8F8F8;color:#999;cursor:not-allowed' : '';
      if (f.type === 'select') {
        var opts = (f.options || []).map(function(o) {
          return '<option value="' + o + '"' + (o === val ? ' selected' : '') + '>' + o + '</option>';
        }).join('');
        var selectStyle = f.readonly ? 'background:#F8F8F8;color:#999;cursor:not-allowed' : '';
        return '<div style="margin-bottom:14px"><label style="display:block;font-size:12px;color:#999;margin-bottom:6px">' + f.label + (f.required ? ' <span style="color:#FF4444">*</span>' : '') + '</label><select class="proto-form-field" data-key="' + f.key + '"' + (f.readonly ? ' disabled' : '') + ' style="width:100%;height:38px;border:1px solid #E0E0E0;border-radius:8px;padding:0 12px;font-size:14px;outline:none;' + selectStyle + '">' + opts + '</select></div>';
      }
      if (f.type === 'image') {
        var imgPreview = val ? '<img src="' + val + '" style="width:100%;height:120px;object-fit:cover;border-radius:8px;margin-top:8px">' : '';
        return '<div style="margin-bottom:14px"><label style="display:block;font-size:12px;color:#999;margin-bottom:6px">' + f.label + (f.required ? ' <span style="color:#FF4444">*</span>' : '') + '</label>' +
          '<div class="proto-form-upload" data-key="' + f.key + '" style="position:relative;width:100%;height:100px;border:2px dashed #E0E0E0;border-radius:8px;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;transition:border-color 0.2s;background:#FAFAFA">' +
          '<svg width="28" height="28" viewBox="0 0 24 24" fill="#CCC"><path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/></svg>' +
          '<span style="font-size:12px;color:#999;margin-top:6px">点击上传图片</span>' +
          '<span style="font-size:10px;color:#CCC;margin-top:2px">支持 JPG/PNG，建议 750×300</span>' +
          '<input type="file" accept="image/*" style="position:absolute;inset:0;opacity:0;cursor:pointer">' +
          '</div>' +
          '<div class="proto-form-img-preview" data-key="' + f.key + '">' + imgPreview + '</div>' +
          '<input class="proto-form-field" data-key="' + f.key + '" type="hidden" value="' + val + '" />' +
          '</div>';
      }
      return '<div style="margin-bottom:14px"><label style="display:block;font-size:12px;color:#999;margin-bottom:6px">' + f.label + (f.required ? ' <span style="color:#FF4444">*</span>' : '') + '</label><input class="proto-form-field" data-key="' + f.key + '" type="' + (f.type || 'text') + '" value="' + val + '" placeholder="' + (f.placeholder || '') + '"' + readonlyAttr + ' style="width:100%;height:38px;border:1px solid #E0E0E0;border-radius:8px;padding:0 12px;font-size:14px;outline:none;font-family:var(--font-num);' + readonlyStyle + '" /></div>';
    }).join('');
    modal.innerHTML =
      '<div style="padding:16px 20px;border-bottom:1px solid #F0F0F0;font-size:16px;font-weight:600;display:flex;align-items:center;justify-content:space-between">' +
      '<span>' + title + '</span>' +
      '<svg width="18" height="18" viewBox="0 0 24 24" fill="#999" style="cursor:pointer" onclick="this.closest(\'.proto-modal-mask\').remove()"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg>' +
      '</div>' +
      '<div style="padding:20px;max-height:60vh;overflow-y:auto">' + fieldsHTML + '</div>' +
      '<div style="display:flex;border-top:1px solid #F0F0F0">' +
      '<button class="proto-form-cancel" style="flex:1;padding:14px;border:none;background:none;font-size:15px;color:#999;cursor:pointer;transition:background .15s">取消</button>' +
      '<button class="proto-form-save" style="flex:1;padding:14px;border:none;background:none;font-size:15px;color:#FF6B3D;font-weight:600;cursor:pointer;border-left:1px solid #F0F0F0;transition:background .15s">保存</button>' +
      '</div>';
    mask.appendChild(modal);
    document.body.appendChild(mask);
    mask.querySelector('.proto-form-cancel').addEventListener('click', function() { mask.remove(); });
    mask.querySelector('.proto-form-save').addEventListener('click', function() {
      var data = {};
      mask.querySelectorAll('.proto-form-field').forEach(function(el) {
        if (el.tagName === 'SELECT') data[el.dataset.key] = el.value;
        else if (el.type === 'hidden') data[el.dataset.key] = el.value;
        else data[el.dataset.key] = el.value;
      });
      if (onSave) onSave(data);
    });
    mask.addEventListener('click', function(e) { if (e.target === mask) mask.remove(); });
    // 图片上传：文件选择后预览
    mask.querySelectorAll('.proto-form-upload').forEach(function(uploadBox) {
      var key = uploadBox.dataset.key;
      var fileInput = uploadBox.querySelector('input[type="file"]');
      var previewContainer = mask.querySelector('.proto-form-img-preview[data-key="' + key + '"]');
      var hiddenInput = mask.querySelector('input.proto-form-field[data-key="' + key + '"]');
      fileInput.addEventListener('change', function(e) {
        var file = e.target.files[0];
        if (!file) return;
        if (!file.type.match(/image\/(jpg|jpeg|png|gif|webp)/i)) {
          showToast('仅支持 JPG/PNG/GIF/WebP 格式');
          return;
        }
        if (file.size > 5 * 1024 * 1024) {
          showToast('图片大小不能超过 5MB');
          return;
        }
        var reader = new FileReader();
        reader.onload = function(ev) {
          var dataUrl = ev.target.result;
          if (previewContainer) {
            previewContainer.innerHTML = '<img src="' + dataUrl + '" style="width:100%;height:120px;object-fit:cover;border-radius:8px;margin-top:8px">';
          }
          if (hiddenInput) hiddenInput.value = dataUrl;
          uploadBox.style.borderColor = '#00B578';
          uploadBox.style.background = '#F0FBF4';
          showToast('图片上传成功');
        };
        reader.readAsDataURL(file);
      });
      uploadBox.addEventListener('dragover', function(e) { e.preventDefault(); uploadBox.style.borderColor = 'var(--op-brand)'; });
      uploadBox.addEventListener('dragleave', function(e) { uploadBox.style.borderColor = '#E0E0E0'; });
      uploadBox.addEventListener('drop', function(e) {
        e.preventDefault();
        var file = e.dataTransfer.files[0];
        if (file) { fileInput.files = e.dataTransfer.files; fileInput.dispatchEvent(new Event('change')); }
      });
    });
    mask.querySelector('.proto-form-save').addEventListener('click', function() {
      var data = {};
      var hasError = false;
      fields.forEach(function(f) {
        var input = mask.querySelector('[data-key="' + f.key + '"]');
        var val = input ? input.value.trim() : '';
        if (f.required && !val) {
          input.style.borderColor = '#FF4444';
          hasError = true;
        }
        data[f.key] = val;
      });
      if (hasError) {
        showToast('请填写必填项');
        return;
      }
      mask.remove();
      if (onSave) onSave(data);
    });
  }

  // ====== 刷新运营权益商品表格 ======
  function refreshOpGoodsTable() {
    var tbody = document.querySelector('.op-tab-pane[data-pane="goods"] .op-table tbody');
    if (!tbody) return;
    var typeMeta = {
      '出行权益': 'tag blue',
      '住宿权益': 'tag green',
      '游玩权益': 'tag orange',
      '通用权益': 'tag'
    };
    tbody.innerHTML = MEMBER_CONFIG.goods.map(function(g, idx) {
      var stTag = g.status === '上架' ? '<span class="tag green">上架</span>' : '<span class="tag" style="background:#F0F0F0;color:#999">下架</span>';
      var actLabel = g.status === '上架' ? '下架' : '上架';
      var actColor = g.status === '上架' ? 'var(--danger)' : 'var(--success)';
      var stockStr = typeof g.stock === 'number' ? g.stock.toLocaleString() : g.stock;
      var imgHTML = g.img ? '<img src="' + g.img + '" style="width:40px;height:40px;object-fit:cover;border-radius:6px;border:1px solid #EEE">' : '<div style="width:40px;height:40px;border-radius:6px;background:#F5F5F5;display:flex;align-items:center;justify-content:center"><svg width="18" height="18" viewBox="0 0 24 24" fill="#CCC"><path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z"/></svg></div>';
      return '<tr data-goods-idx="' + idx + '">' +
        '<td>' + imgHTML + '</td>' +
        '<td><span class="op-goods-name" data-idx="' + idx + '" style="font-weight:600;cursor:pointer;color:#333">' + g.name + '</span></td>' +
        '<td><span class="' + (typeMeta[g.type] || 'tag') + '">' + g.type + '</span></td>' +
        '<td style="font-family:var(--font-num);color:var(--op-brand);font-weight:600">' + g.coin + '</td>' +
        '<td style="font-family:var(--font-num)">' + stockStr + '</td>' +
        '<td style="color:#666;font-family:var(--font-num)">' + g.exp + '</td>' +
        '<td>' + stTag + '</td>' +
        '<td><span class="op-goods-edit" data-idx="' + idx + '" style="color:var(--op-brand);cursor:pointer;display:inline-flex;align-items:center;gap:2px;font-size:11px"><svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z"/></svg>编辑</span><span class="op-goods-toggle" data-idx="' + idx + '" style="color:' + actColor + ';cursor:pointer;margin-left:10px;font-size:11px">' + actLabel + '</span></td>' +
        '</tr>';
    }).join('');
  }

  // ====== 刷新运营等级规则表格 ======
  function refreshOpLevelTable(side) {
    var pane = document.querySelector('.op-tab-pane[data-pane="' + (side === 'c' ? 'c-rule' : 'b-rule') + '"]');
    if (!pane) return;
    var tbody = pane.querySelector('.op-table tbody');
    if (!tbody) return;
    var levels = side === 'c' ? MEMBER_CONFIG.cLevels : MEMBER_CONFIG.bLevels;
    if (side === 'c') {
      tbody.innerHTML = levels.map(function(l, idx) {
        return '<tr data-level-idx="' + idx + '">' +
          '<td><span class="' + l.cls + '" ' + l.st + '>' + l.name + '</span></td>' +
          '<td><input class="op-mini-input op-level-input" data-idx="' + idx + '" data-key="min" value="' + l.min + '" style="width:80px" /></td>' +
          '<td><input class="op-mini-input op-level-input" data-idx="' + idx + '" data-key="max" value="' + l.max + '" style="width:80px" /></td>' +
          '<td><div style="display:flex;align-items:center;gap:4px"><input class="op-mini-input op-level-input" data-idx="' + idx + '" data-key="mult" value="' + l.mult + '" style="width:60px" /><span style="font-size:12px;color:#999">x</span></div></td>' +
          '<td><input class="op-mini-input op-level-input" data-idx="' + idx + '" data-key="coin" value="' + l.coin + '" style="width:80px" /></td>' +
          '<td><span class="tag green">' + l.status + '</span></td>' +
          '</tr>';
      }).join('');
    } else {
      tbody.innerHTML = levels.map(function(l, idx) {
        return '<tr data-level-idx="' + idx + '">' +
          '<td><span class="' + l.cls + '" ' + l.st + '>' + l.name + '</span></td>' +
          '<td><div style="display:flex;align-items:center;gap:4px"><input class="op-mini-input op-level-input" data-idx="' + idx + '" data-key="min" value="' + l.min + '" style="width:60px" /><span style="color:#999;font-size:12px">-</span><input class="op-mini-input op-level-input" data-idx="' + idx + '" data-key="max" value="' + l.max + '" style="width:60px" /><span style="font-size:12px;color:#999">万</span></div></td>' +
          '<td><div style="display:flex;align-items:center;gap:4px"><input class="op-mini-input op-level-input" data-idx="' + idx + '" data-key="rate" value="' + l.rate + '" style="width:60px" /><span style="font-size:12px;color:#999">%</span></div></td>' +
          '<td><div style="display:flex;align-items:center;gap:4px"><input class="op-mini-input op-level-input" data-idx="' + idx + '" data-key="rights" value="' + l.rights + '" style="width:60px" /><span style="font-size:12px;color:#999">项</span></div></td>' +
          '<td><span class="tag green">' + l.status + '</span></td>' +
          '</tr>';
      }).join('');
    }
  }

  // ====== 刷新权益映射表格 ======
  function refreshBenefitMapTable(side) {
    var pane = document.querySelector('.op-tab-pane[data-pane="' + (side === 'c' ? 'c-map' : 'b-map') + '"]');
    if (!pane) return;
    var tbody = pane.querySelector('.op-table tbody');
    if (!tbody) return;
    var benefits = side === 'c' ? MEMBER_CONFIG.cBenefits : MEMBER_CONFIG.bBenefits;
    var levels = side === 'c' ? MEMBER_CONFIG.cLevels : MEMBER_CONFIG.bLevels;
    tbody.innerHTML = benefits.map(function(b, bi) {
      var cells = b.map.map(function(on, li) {
        return '<td style="text-align:center"><span class="op-map-cell ' + (on ? 'op-map-on' : 'op-map-off') + '" data-bi="' + bi + '" data-li="' + li + '" data-side="' + side + '">' + (on ? '✓' : '—') + '</span></td>';
      }).join('');
      return '<tr data-benefit-idx="' + bi + '"><td style="font-weight:500">' + b.name + '</td>' + cells + '</tr>';
    }).join('');
  }

  // ====== 运营PC 会员详情弹窗 ======
  function showOpMemberDetail(row) {
    if (!row) return;
    var cells = row.querySelectorAll('td');
    var id = cells[0] ? cells[0].textContent.trim() : '';
    var name = cells[1] ? cells[1].textContent.trim() : '';
    var phone = cells[2] ? cells[2].textContent.trim() : '';
    var level = cells[3] ? cells[3].textContent.trim() : '';
    var reg = cells[4] ? cells[4].textContent.trim() : '';
    var spend = cells[5] ? cells[5].textContent.trim() : '';
    var coin = cells[6] ? cells[6].textContent.trim() : '';
    var status = cells[7] ? cells[7].textContent.trim() : '';

    var levelColors = { 'U粉': '#FF6B3D', 'U享': '#4A90D9', 'U尊': '#7C3AED', 'U黑金': '#D4AF37' };
    var lvColor = levelColors[level] || '#999';
    var statusColor = status === '正常' ? '#00B578' : status === '冻结' ? '#FF4444' : '#999';

    // 根据等级查找权益映射
    var lvIdx = -1;
    var lvNames = MEMBER_CONFIG.cLevels.map(function(l) { return l.name; });
    lvIdx = lvNames.indexOf(level);
    var benefitList = lvIdx >= 0 ? MEMBER_CONFIG.cBenefits.filter(function(b) { return b.map[lvIdx]; }).map(function(b) { return b.name; }) : [];

    // 模拟消费记录（基于会员ID生成稳定假数据）
    var orders = [
      { date: '2026-07-15', route: '泰国曼谷5日游', amount: '¥3,280', status: '已完成' },
      { date: '2026-05-20', route: '日本京都樱花团', amount: '¥6,580', status: '已完成' },
      { date: '2026-03-08', route: '海南三亚自由行', amount: '¥2,180', status: '已完成' },
      { date: '2025-12-25', route: '欧洲法瑞意13日', amount: '¥18,800', status: '已完成' }
    ];

    // 等级变动历史
    var levelHistory = [];
    levelHistory.push({ date: reg, text: '注册成为会员', level: 'U粉' });
    if (level !== 'U粉') {
      levelHistory.push({ date: '2024-08-01', text: '成长值达标，升级至', level: level });
    }

    var content =
      '<div style="padding:24px">' +
      // === 会员头部信息 ===
      '<div style="display:flex;align-items:center;gap:16px;margin-bottom:20px;padding-bottom:20px;border-bottom:1px solid #F0F0F0">' +
      '<div style="width:56px;height:56px;border-radius:50%;background:' + lvColor + ';color:#fff;display:flex;align-items:center;justify-content:center;font-size:24px;font-weight:700;flex-shrink:0">' + (name[0] || 'U') + '</div>' +
      '<div style="flex:1">' +
        '<div style="font-size:18px;font-weight:600;color:#1C1C1E">' + name + '</div>' +
        '<div style="font-size:13px;color:#999;margin-top:4px">会员ID: ' + id + ' · ' + phone + '</div>' +
      '</div>' +
      '<div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px">' +
        '<span style="padding:4px 14px;border-radius:20px;background:' + lvColor + '15;color:' + lvColor + ';font-size:13px;font-weight:600">' + level + '</span>' +
        '<span style="padding:3px 10px;border-radius:12px;background:' + (status === '正常' ? '#E8F5E9' : status === '冻结' ? '#FFEBEE' : '#F5F5F5') + ';color:' + statusColor + ';font-size:11px;font-weight:600">' + status + '</span>' +
      '</div>' +
      '</div>' +
      // === 基础信息卡片 ===
      '<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-bottom:20px">' +
        '<div style="background:#F8F9FA;border-radius:10px;padding:14px"><div style="font-size:11px;color:#999;margin-bottom:4px">注册时间</div><div style="font-size:14px;font-weight:600;color:#333;font-family:var(--font-num)">' + reg + '</div></div>' +
        '<div style="background:#F8F9FA;border-radius:10px;padding:14px"><div style="font-size:11px;color:#999;margin-bottom:4px">累计消费</div><div style="font-size:14px;font-weight:600;color:#333;font-family:var(--font-num)">' + spend + '</div></div>' +
        '<div style="background:#F8F9FA;border-radius:10px;padding:14px"><div style="font-size:11px;color:#999;margin-bottom:4px">U币余额</div><div style="font-size:14px;font-weight:600;color:#FF6B3D;font-family:var(--font-num)">' + coin + '</div></div>' +
        '<div style="background:#F8F9FA;border-radius:10px;padding:14px"><div style="font-size:11px;color:#999;margin-bottom:4px">消费倍率</div><div style="font-size:14px;font-weight:600;color:#333;font-family:var(--font-num)">' + (lvIdx >= 0 ? MEMBER_CONFIG.ucoinRules.mult[lvIdx].val : '1') + 'x</div></div>' +
      '</div>' +
      // === 享有权益 ===
      '<div style="margin-bottom:20px">' +
        '<div style="font-size:13px;font-weight:600;color:#333;margin-bottom:10px">享有权益 <span style="color:#999;font-weight:400">(' + benefitList.length + '项)</span></div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:8px">' +
          (benefitList.length > 0 ? benefitList.map(function(b) {
            return '<span style="padding:5px 12px;border-radius:6px;background:#FFF3E0;color:#FF6B3D;font-size:12px;font-weight:500">' + b + '</span>';
          }).join('') : '<span style="font-size:12px;color:#999">暂无权益</span>') +
        '</div>' +
      '</div>' +
      // === 消费记录 ===
      '<div style="margin-bottom:20px">' +
        '<div style="font-size:13px;font-weight:600;color:#333;margin-bottom:10px">消费记录</div>' +
        '<div style="border:1px solid #F0F0F0;border-radius:10px;overflow:hidden">' +
          '<table style="width:100%;border-collapse:collapse;font-size:12px">' +
            '<thead><tr style="background:#FAFAFA"><th style="padding:8px 12px;text-align:left;font-weight:600;color:#666">日期</th><th style="padding:8px 12px;text-align:left;font-weight:600;color:#666">线路</th><th style="padding:8px 12px;text-align:right;font-weight:600;color:#666">金额</th><th style="padding:8px 12px;text-align:center;font-weight:600;color:#666">状态</th></tr></thead>' +
            '<tbody>' +
              orders.map(function(o) {
                return '<tr style="border-bottom:1px solid #F5F5F5"><td style="padding:8px 12px;color:#666;font-family:var(--font-num)">' + o.date + '</td><td style="padding:8px 12px;color:#333;font-weight:500">' + o.route + '</td><td style="padding:8px 12px;text-align:right;font-family:var(--font-num);font-weight:600">' + o.amount + '</td><td style="padding:8px 12px;text-align:center"><span class="tag green">' + o.status + '</span></td></tr>';
              }).join('') +
            '</tbody>' +
          '</table>' +
        '</div>' +
      '</div>' +
      // === 等级变动时间线 ===
      '<div style="margin-bottom:20px">' +
        '<div style="font-size:13px;font-weight:600;color:#333;margin-bottom:10px">等级变动历史</div>' +
        '<div style="position:relative;padding-left:20px">' +
          levelHistory.map(function(h, i) {
            var hc = levelColors[h.level] || '#999';
            var isLast = i === levelHistory.length - 1;
            return '<div style="position:relative;padding-bottom:' + (isLast ? '0' : '16px') + '">' +
              '<div style="position:absolute;left:-20px;top:3px;width:10px;height:10px;border-radius:50%;background:' + hc + ';border:2px solid #fff;box-shadow:0 0 0 2px ' + hc + '20"></div>' +
              (isLast ? '' : '<div style="position:absolute;left:-16px;top:14px;bottom:0;width:2px;background:#E0E0E0"></div>') +
              '<div style="font-size:12px;color:#999;font-family:var(--font-num)">' + h.date + '</div>' +
              '<div style="font-size:13px;color:#333;margin-top:2px">' + h.text + ' <span style="color:' + hc + ';font-weight:600">' + h.level + '</span></div>' +
            '</div>';
          }).join('') +
        '</div>' +
      '</div>' +
      // === 底部操作按钮 ===
      '<div style="display:flex;gap:10px;padding-top:16px;border-top:1px solid #F0F0F0">' +
        '<button onclick="this.closest(\'.proto-detail-mask\').remove()" style="flex:1;padding:11px;background:#F5F5F5;color:#666;border:none;border-radius:10px;font-size:14px;font-weight:600;cursor:pointer">关闭</button>' +
        '<button onclick="showToast(\'报告已生成，请到下载中心查看\');this.closest(\'.proto-detail-mask\').remove()" style="flex:1;padding:11px;background:linear-gradient(135deg,#FF6B3D,#FF8A5C);color:#fff;border:none;border-radius:10px;font-size:14px;font-weight:600;cursor:pointer">导出报告</button>' +
      '</div>' +
      '</div>';

    showDetailModal('会员详情 · ' + name, content, { width: 600 });
  }

