    var data = {
      today: { flow: '¥12,580.00', price: '¥3,145.00', contract: '¥11,200.00', settle: '¥10,800.00' },
      yesterday: { flow: '¥8,920.00', price: '¥2,230.00', contract: '¥7,800.00', settle: '¥7,500.00' },
      week: { flow: '¥56,340.00', price: '¥2,817.00', contract: '¥52,100.00', settle: '¥50,200.00' },
      month: { flow: '¥186,500.00', price: '¥2,665.00', contract: '¥175,000.00', settle: '¥168,000.00' }
    };
    var d = data[period] || data.today;
    var els = {
      flow: document.querySelector('.core-flow'),
      price: document.querySelector('.core-price'),
      contract: document.querySelector('.core-contract'),
      settle: document.querySelector('.core-settle')
    };
